// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address target = makeAddr("target");
        uint amount = 0.5 ether;
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        vm.prank(address(this));
        c.sendMoney(target, amount);
        assertTrue(address(target).balance == amount);
    }
}
